// 综艺花字 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、popText()（多层描边 + 硬投影花字）、pop()（回弹）、slam()（冲击）、shake()（落地抖动）、
// burst()（爆炸星）、sticker()（贴纸底板）、ring()（贴纸语言的高亮圈）、arrow()（箭头道具）、actionLines()（冲击线）、stripes()（斜条纹底），
// 以及 layers() 的分层写法：每个花字、贴纸各成一层，弹出、砸落、抖动都写进 pose(t)，运行时据此做运动模糊。

const STYLE = {
  color: {
    bg: "#FFD60A",
    stripe: "#FFC300",
    ink: "#111111",
    white: "#FFFFFF",
    red: "#FF2D2D",
    blue: "#1E6BFF",
  },
  font: {
    title: '"YouSheBiaoTiYuan", "Alimama FangYuanTi VF", "HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
    body: '"Alimama FangYuanTi VF", "HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
  },
};

// 快切：每段的花字弹出、强调完就快速收走（0.15 s 缩小消失），下一段几乎同时砸进来。
const SCENES = { title: [0, 2.0], keyword: [1.92, 3.7], media: [3.62, 6.3], data: [6.27, 8.2], name: [8.12, 9.6], end: [9.52, 99] };
const COPY = {
  title: ["把想法", "变成画面"],
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率！" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
// backOut：过冲约 10%。
const backOut = (v, c = 1.6) => { v = clamp(v) - 1; return 1 + (c + 1) * v * v * v + c * v * v; };
const quintOut = (v) => 1 - Math.pow(1 - clamp(v), 5);
const cubicIn = (v) => clamp(v) ** 3;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 弹出：0 → 1 带过冲，0.3 s。
function pop(t, start, dur = 0.3) { return t < start ? 0 : backOut((t - start) / dur); }
// 冲击：从 1.6 倍砸到 1 倍，0.18 s，几乎没有过渡。
function slam(t, start, dur = 0.18) { return t < start ? null : 1 + 0.6 * (1 - quintOut((t - start) / dur)); }
// 落地抖动：落地后 0.3 s 内衰减，确定性正弦。
function shake(t, start, amp) {
  const k = t - start;
  if (k < 0 || k > 0.3) return [0, 0];
  const d = amp * (1 - k / 0.3);
  return [Math.sin(k * 90) * d, Math.cos(k * 70) * d * 0.6];
}

function stripes(ctx, t, u, w, h) {
  ctx.fillStyle = STYLE.color.bg;
  ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.fillStyle = STYLE.color.stripe;
  const step = 70 * u, off = (t * 60 * u) % step;
  ctx.translate(w / 2, h / 2);
  ctx.rotate(-Math.PI / 6);
  for (let x = -w - off; x < w; x += step) ctx.fillRect(x, -w, step / 2, w * 2);
  ctx.restore();
}

// 花字，由外到内：黑色硬投影 → 白色外描边 → 黑色内描边 → 填色。
// 两条规则保证复杂字（"画""想""赢"）的内部空隙不被填死：
// 1. 字重只写字体实际有的。优设标题圆只有一个字重，写 700/900 会被浏览器假加粗。
// 2. 描边宽度按字号封顶：外描边总宽不超过字号的 16%，内描边不超过 5%。描边是沿笔画边缘向两侧长的，太粗就会长进字内的空隙。
// 填色和内描边要反差大（白字配黑边），否则字形会糊成一团。
const TITLE_WEIGHT = 400;
function popText(ctx, text, x, y, size, fill, u, align = "center") {
  ctx.font = font(TITLE_WEIGHT, size, STYLE.font.title);
  ctx.textAlign = align;
  ctx.lineJoin = "round";
  const outer = Math.min(size * 0.16, 22 * u), inner = Math.min(size * 0.05, 6 * u), sh = outer * 0.5;
  ctx.lineWidth = outer;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.strokeText(text, x + sh, y + sh);
  ctx.strokeStyle = STYLE.color.white;
  ctx.strokeText(text, x, y);
  ctx.lineWidth = inner;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = fill;
  ctx.fillText(text, x, y);
  ctx.textAlign = "left";
}

function burst(ctx, cx, cy, r, spikes, rot, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  for (let i = 0; i < spikes * 2; i++) {
    const a = rot + (i * Math.PI) / spikes, rr = i % 2 ? r * 0.72 : r;
    ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
  }
  ctx.closePath();
  ctx.fill();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 贴纸底板：粗黑边 + 硬投影。
function sticker(ctx, x, y, w, h, color, u, r = 18 * u) {
  roundRect(ctx, x + 8 * u, y + 8 * u, w, h, r);
  ctx.fillStyle = STYLE.color.ink;
  ctx.fill();
  roundRect(ctx, x, y, w, h, r);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 5 * u;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.stroke();
}

// 高亮圈：和花字同一套层次——硬投影 → 白色外圈 → 红圈，圈住目标。
function ring(ctx, x, y, w, h, u) {
  const r = h / 2;
  ctx.lineJoin = "round";
  roundRect(ctx, x + 5 * u, y + 5 * u, w, h, r); ctx.lineWidth = 14 * u; ctx.strokeStyle = STYLE.color.ink; ctx.stroke();
  roundRect(ctx, x, y, w, h, r); ctx.strokeStyle = STYLE.color.white; ctx.stroke();
  ctx.lineWidth = 7 * u; ctx.strokeStyle = STYLE.color.red; ctx.stroke();
}

// 箭头道具：贴纸造型（粗黑边 + 硬投影），本地坐标里箭头指向右方，尖端在原点。
function arrow(ctx, u, color = STYLE.color.blue) {
  const shape = (dx, dy) => {
    ctx.beginPath();
    ctx.moveTo(dx, dy); ctx.lineTo(dx - 46 * u, dy - 34 * u); ctx.lineTo(dx - 46 * u, dy - 14 * u); ctx.lineTo(dx - 110 * u, dy - 14 * u);
    ctx.lineTo(dx - 110 * u, dy + 14 * u); ctx.lineTo(dx - 46 * u, dy + 14 * u); ctx.lineTo(dx - 46 * u, dy + 34 * u); ctx.closePath();
  };
  shape(6 * u, 6 * u); ctx.fillStyle = STYLE.color.ink; ctx.fill();
  shape(0, 0); ctx.fillStyle = color; ctx.fill(); ctx.lineWidth = 5 * u; ctx.lineJoin = "round"; ctx.strokeStyle = STYLE.color.ink; ctx.stroke();
}

// 冲击线：三条粗黑短线从角上向外放射，像漫画里的强调符号。
function actionLines(ctx, u, k) {
  ctx.strokeStyle = STYLE.color.ink; ctx.lineCap = "round"; ctx.lineWidth = 8 * u;
  [[-0.5, 0], [0, 1], [0.5, 0.5]].forEach(([a, i]) => {
    const ang = -Math.PI / 4 + a, r0 = 18 * u, r1 = r0 + (40 + i * 10) * u * k;
    ctx.beginPath(); ctx.moveTo(Math.cos(ang) * r0, Math.sin(ang) * r0); ctx.lineTo(Math.cos(ang) * r1, Math.sin(ang) * r1); ctx.stroke();
  });
}

// 示意画面：一块亮色的编辑界面（预览、属性栏、时间线），本地坐标原点在左上角；高亮目标是属性栏里的红色按钮。
function mockTarget(iw, ih) { return { x: iw * 0.69, y: ih * 0.46, w: iw * 0.24, h: ih * 0.1 }; }
function mockScreen(ctx, iw, ih, u) {
  ctx.fillStyle = "#FFFFFF"; ctx.fillRect(0, 0, iw, ih);
  ctx.fillStyle = "#F1F1F1"; ctx.fillRect(0, 0, iw, ih * 0.08);
  ["#FF2D2D", "#FFD60A", "#1E6BFF"].forEach((c, i) => { ctx.fillStyle = c; ctx.beginPath(); ctx.arc((16 + i * 15) * u, ih * 0.04, 4.5 * u, 0, Math.PI * 2); ctx.fill(); });
  const px = iw * 0.035, py = ih * 0.13, pw = iw * 0.6, ph = ih * 0.54;
  ctx.fillStyle = "#7FB2FF"; ctx.fillRect(px, py, pw, ph);
  ctx.save(); ctx.beginPath(); ctx.rect(px, py, pw, ph); ctx.clip();
  burst(ctx, px + pw * 0.7, py + ph * 0.34, ph * 0.16, 10, 0.2, "#FFD60A");
  const hill = (k, color, lift) => {
    ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(px, py + ph);
    for (let i = 0; i <= 10; i++) ctx.lineTo(px + (pw * i) / 10, py + ph * (lift - 0.1 * Math.sin(i * 1.1 + k)));
    ctx.lineTo(px + pw, py + ph); ctx.closePath(); ctx.fill();
  };
  hill(0.4, "#3B8BFF", 0.7); hill(2.2, "#1E6BFF", 0.88);
  ctx.restore();
  ctx.lineWidth = 3 * u; ctx.strokeStyle = STYLE.color.ink; ctx.strokeRect(px, py, pw, ph);
  const sx = iw * 0.67, sw = iw * 0.29;
  [0.9, 0.55, 0.75, 0.45].forEach((k, i) => { ctx.fillStyle = "#E3E3E3"; ctx.fillRect(sx, py + ih * (0.02 + i * 0.07), sw * k, ih * 0.026); });
  const T = mockTarget(iw, ih);
  roundRect(ctx, T.x, T.y, T.w, T.h, T.h / 2); ctx.fillStyle = STYLE.color.red; ctx.fill();
  ctx.fillStyle = "#FFFFFF"; ctx.fillRect(T.x + T.w * 0.25, T.y + T.h * 0.42, T.w * 0.5, T.h * 0.16);
  const ty = py + ph + ih * 0.07, lanes = [[0, 0.3, 0.32, 0.36], [0.06, 0.48, 0.58, 0.3], [0, 0.22, 0.26, 0.5]];
  lanes.forEach((row, i) => { for (let j = 0; j < row.length; j += 2) { ctx.fillStyle = ["#E3E3E3", "#FFB3B3", "#E3E3E3"][i]; ctx.fillRect(px + iw * 0.93 * row[j], ty + i * ih * 0.055, iw * 0.93 * row[j + 1], ih * 0.035); } });
}

const within = (t, [a, b]) => t >= a && t < b;
const fadeOut = (t, [, b], dur = 0.15) => 1 - cubicIn((t - (b - dur)) / dur);
// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return measurer.measureText(text).width;
}

function layers(_params, w, h) {
  const u = h / 720, C = STYLE.color, out = [];
  // 底：斜条纹按当前时刻整层画（匀速慢移，不需要模糊）。
  out.push({ draw: (ctx, t) => stripes(ctx, t, u, w, h) });

  // 标题：爆炸星转着弹出当底板（标题框），两行花字错开、各自微微倾斜依次弹出。不加副标题。
  const title = SCENES.title;
  out.push({
    bounds: [-335 * u, -335 * u, 335 * u, 335 * u],
    pose: (t) => within(t, title) ? { x: w * 0.5, y: h * 0.5, rotation: t * 0.4, scale: pop(t, 0, 0.4) * fadeOut(t, title) } : null,
    draw: (ctx) => burst(ctx, 0, 0, 330 * u, 14, 0, C.red),
  });
  out.push({
    bounds: [-220 * u, -120 * u, 230 * u, 45 * u],
    pose: (t) => within(t, title) ? { x: w * 0.47, y: h * 0.45, rotation: -0.07, scale: pop(t, 0.05) * fadeOut(t, title) } : null,
    draw: (ctx) => popText(ctx, COPY.title[0], 0, 0, 120 * u, C.white, u),
  });
  out.push({
    bounds: [-300 * u, -130 * u, 310 * u, 50 * u],
    pose: (t) => within(t, title) ? { x: w * 0.53, y: h * 0.68, rotation: -0.05, scale: pop(t, 0.15) * fadeOut(t, title) } : null,
    draw: (ctx) => popText(ctx, COPY.title[1], 0, 0, 132 * u, C.bg, u),
  });

  // 花字与关键词：“风格”装在黑色胶囊里先弹出；“不走样”红色大花字从 1.6 倍砸下、落地抖一下，冲击线随后在角上弹出。
  const kw = SCENES.keyword, keyStart = kw[0] + 0.18, keyFont = font(TITLE_WEIGHT, 170 * u, STYLE.font.title), keyW = measure(COPY.keyword.key, keyFont);
  out.push({
    bounds: [-100 * u, -42 * u, 100 * u, 36 * u],
    pose: (t) => within(t, kw) ? { x: w * 0.5 - keyW * 0.3, y: h * 0.38, rotation: -0.06, scale: pop(t, kw[0], 0.25) * fadeOut(t, kw) } : null,
    draw: (ctx) => {
      ctx.font = font(700, 44 * u, STYLE.font.body);
      const tw = ctx.measureText(COPY.keyword.lead).width;
      roundRect(ctx, -tw / 2 - 28 * u, -38 * u, tw + 56 * u, 70 * u, 35 * u); ctx.fillStyle = C.ink; ctx.fill();
      ctx.fillStyle = C.white; ctx.textAlign = "center"; ctx.fillText(COPY.keyword.lead, 0, 12 * u); ctx.textAlign = "left";
    },
  });
  out.push({
    bounds: [-keyW / 2 - 40 * u, -150 * u, keyW / 2 + 50 * u, 50 * u],
    pose: (t) => {
      const sc = slam(t, keyStart);
      if (!within(t, kw) || sc == null) return null;
      const [dx, dy] = shake(t, keyStart + 0.18, 9 * u);
      return { x: w * 0.5 + dx, y: h * 0.62 + dy, rotation: 0.04, scale: sc * fadeOut(t, kw) };
    },
    draw: (ctx) => popText(ctx, COPY.keyword.key, 0, 0, 170 * u, C.red, u),
  });
  out.push({
    bounds: [-10 * u, -90 * u, 90 * u, 10 * u],
    pose: (t) => within(t, kw) && t >= keyStart + 0.2 ? { x: w * 0.5 + keyW / 2 + 6 * u, y: h * 0.62 - 120 * u, scale: fadeOut(t, kw) } : null,
    draw: (ctx, t) => actionLines(ctx, u, backOut((t - keyStart - 0.2) / 0.25)),
  });

  // 图片与录屏容器 + 高亮：截图贴在白色贴纸底板上（粗黑边 + 硬投影），整块从 1.15 倍砸下、落地抖一下；
  // 角上黑色胶囊写“示意画面”。高亮：红色高亮圈弹出圈住目标，蓝色箭头贴纸随后砸到旁边指着它。
  const media = SCENES.media, land = media[0] + 0.05, iw = w * 0.56, ih = iw * 9 / 16, pad = 16 * u;
  const T = mockTarget(iw, ih), hlAt = media[0] + 1.15;
  const plate = (t) => {
    if (!within(t, media)) return null;
    const k = pop(t, land, 0.35), [dx, dy] = shake(t, land + 0.3, 6 * u);
    return k > 0 ? { x: w * 0.47 + dx, y: h * 0.52 + dy, rotation: -0.03, scale: (1.15 - 0.15 * k) * Math.min(1, k * 3) * fadeOut(t, media) } : null;
  };
  out.push({
    bounds: [-iw / 2 - pad - 4 * u, -ih / 2 - pad - 4 * u, iw / 2 + pad + 12 * u, ih / 2 + pad + 12 * u],
    pose: plate,
    draw: (ctx, t) => {
      sticker(ctx, -iw / 2 - pad, -ih / 2 - pad, iw + 2 * pad, ih + 2 * pad, C.white, u);
      ctx.save(); ctx.translate(-iw / 2, -ih / 2); mockScreen(ctx, iw, ih, u);
      const k = pop(t, hlAt, 0.3);
      if (k > 0) {
        const s = 0.4 + 0.6 * k, cx = T.x + T.w / 2, cy = T.y + T.h / 2, rw = (T.w + 30 * u) * s, rh = (T.h + 26 * u) * s;
        ring(ctx, cx - rw / 2, cy - rh / 2, rw, rh, u);
      }
      ctx.restore();
    },
  });
  out.push({
    bounds: [-80 * u, -22 * u, 80 * u, 22 * u],
    pose: (t) => { const p = plate(t); return p && t >= land + 0.15 ? { x: w * 0.47 - iw / 2 + 60 * u, y: h * 0.52 - ih / 2 - pad - 4 * u, rotation: -0.06, scale: pop(t, land + 0.15, 0.25) * fadeOut(t, media) } : null; },
    draw: (ctx) => {
      ctx.font = font(700, 20 * u, STYLE.font.body);
      const tw = ctx.measureText(COPY.media).width;
      roundRect(ctx, -tw / 2 - 16 * u, -19 * u, tw + 32 * u, 38 * u, 19 * u); ctx.fillStyle = C.ink; ctx.fill();
      ctx.fillStyle = C.white; ctx.textAlign = "center"; ctx.fillText(COPY.media, 0, 7 * u); ctx.textAlign = "left";
    },
  });
  // 箭头尖指向高亮圈的左缘（跟随底板的位置与倾斜换算到画面坐标）。
  const tipLocal = [T.x - iw / 2 - 20 * u, T.y + T.h / 2 - ih / 2 + 10 * u], rot = -0.03;
  const tip = [w * 0.47 + tipLocal[0] * Math.cos(rot) - tipLocal[1] * Math.sin(rot), h * 0.52 + tipLocal[0] * Math.sin(rot) + tipLocal[1] * Math.cos(rot)];
  out.push({
    bounds: [-120 * u, -42 * u, 14 * u, 42 * u],
    pose: (t) => {
      const sc = slam(t, hlAt + 0.15);
      if (!within(t, media) || sc == null) return null;
      const [dx, dy] = shake(t, hlAt + 0.33, 5 * u);
      return { x: tip[0] + dx - (sc - 1) * 60 * u, y: tip[1] + dy, rotation: -0.35, scale: sc * fadeOut(t, media) };
    },
    draw: (ctx) => arrow(ctx, u),
  });

  // 数据：数字快速蹦到终值，落地瞬间砸一下再抖；对话气泡随后弹出。
  const data = SCENES.data, dland = data[0] + 0.55;
  out.push({
    bounds: [-270 * u, -210 * u, 280 * u, 50 * u],
    pose: (t) => {
      if (!within(t, data)) return null;
      const sc = t < dland ? 0.9 + 0.1 * clamp((t - data[0]) / 0.55) : slam(t, dland, 0.2);
      const [dx, dy] = shake(t, dland, 10 * u);
      return { x: w * 0.45 + dx, y: h * 0.6 + dy, rotation: -0.05, scale: sc * fadeOut(t, data) * pop(t, data[0], 0.25) };
    },
    draw: (ctx, t) => popText(ctx, `${Math.round(COPY.data.value * quintOut((t - data[0]) / 0.55))}${COPY.data.unit}`, 0, 0, 230 * u, C.red, u),
  });
  out.push({
    bounds: [-200 * u, -52 * u, 210 * u, 100 * u],
    pose: (t) => within(t, data) ? { x: w * 0.76, y: h * 0.25, rotation: 0.08, scale: pop(t, dland + 0.1, 0.3) * fadeOut(t, data) } : null,
    draw: (ctx) => {
      ctx.font = font(TITLE_WEIGHT, 40 * u, STYLE.font.title);
      const tw = ctx.measureText(COPY.data.label).width;
      // 对话气泡：白底黑边 + 小尾巴。
      ctx.beginPath();
      ctx.moveTo(-40 * u, 40 * u); ctx.lineTo(-70 * u, 92 * u); ctx.lineTo(-4 * u, 40 * u); ctx.closePath();
      ctx.fillStyle = C.white; ctx.fill();
      ctx.lineWidth = 5 * u; ctx.strokeStyle = C.ink; ctx.stroke();
      sticker(ctx, -tw / 2 - 28 * u, -44 * u, tw + 56 * u, 88 * u, C.white, u);
      ctx.fillStyle = C.ink;
      ctx.textAlign = "center";
      ctx.fillText(COPY.data.label, 0, 14 * u);
      ctx.textAlign = "left";
    },
  });

  // 人名条：白色贴纸卡片弹出，角上的小爆炸星转着弹出。
  const name = SCENES.name;
  out.push({
    bounds: [-192 * u, -72 * u, 200 * u, 80 * u],
    pose: (t) => within(t, name) ? { x: w * 0.3, y: h * 0.74, rotation: -0.04, scale: pop(t, name[0] + 0.05, 0.35) * fadeOut(t, name) } : null,
    draw: (ctx) => {
      sticker(ctx, -190 * u, -70 * u, 380 * u, 140 * u, C.white, u);
      ctx.fillStyle = C.ink;
      ctx.font = font(TITLE_WEIGHT, 56 * u, STYLE.font.title);
      ctx.fillText(COPY.name.name, -150 * u, 8 * u);
      ctx.fillStyle = C.blue;
      ctx.font = font(700, 26 * u, STYLE.font.body);
      ctx.fillText(COPY.name.role, -150 * u, 48 * u);
    },
  });
  out.push({
    bounds: [-36 * u, -36 * u, 36 * u, 36 * u],
    pose: (t) => within(t, name) ? { x: w * 0.3 + 190 * u, y: h * 0.74 - 70 * u, rotation: t * 2, scale: pop(t, name[0] + 0.25, 0.3) * fadeOut(t, name) } : null,
    draw: (ctx) => burst(ctx, 0, 0, 34 * u, 8, 0, C.red),
  });

  // 收尾：逐字从下方蹦出，后半句换红色，落地后随节拍轻轻起伏。每个字一层。
  const end = SCENES.end, chars = [...COPY.end], f = font(TITLE_WEIGHT, 84 * u, STYLE.font.title);
  const widths = chars.map((c) => measure(c, f));
  let x = w / 2 - widths.reduce((a, b) => a + b, 0) / 2;
  chars.forEach((c, i) => {
    const start = end[0] + 0.05 + i * 0.05, cx = x + widths[i] / 2;
    out.push({
      bounds: [-60 * u, -95 * u, 66 * u, 40 * u],
      pose: (t) => {
        if (t < start) return null;
        const k = pop(t, start, 0.3), bob = t > start + 0.3 ? Math.sin((t - start) * 9 + i) * 4 * u : 0;
        return { x: cx, y: h * 0.56 - (1 - k) * 60 * u + bob, rotation: (i % 2 ? 1 : -1) * 0.04, scale: k };
      },
      draw: (ctx) => popText(ctx, c, 0, 0, 84 * u, i >= 5 ? C.red : C.white, u),
    });
    x += widths[i];
  });
  return out;
}

